def quantity(value):
    if type(value) not in (str, int, float) or isinstance(value, bool):
        raise Unavailable("malformed Kubernetes quantity")
    match = re.fullmatch(r"([0-9]+(?:\.[0-9]+)?)([EPTGMK]i|[eE][+-]?[0-9]+|[numkMGTPE])?", str(value))
    if not match:
        raise Unavailable("malformed Kubernetes quantity")
    return Decimal(match[1])

